const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  return chunks;
};

describe('ChatOrchestrator tool loop', () => {
  it('feeds a rejected tool call back to the provider so a corrected retry can resolve', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'gets things up',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let round = 0;
    let rejection = '';
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'bad-call', name: 'get_weather', input: {}}};
          yield STOP_FOR_TOOL;
          return;
        }
        if (round === 2) {
          const toolResultMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          rejection = toolResultMessage.content[0]?.content ?? '';
          yield {type: 'tool_use', toolCall: {id: 'good-call', name: 'get_weather', input: {location: 'Paris'}}};
          yield STOP_FOR_TOOL;
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield STOP_DONE;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
